export async function listTools() {
  return [
    {
      name: 'users_get_many',
      description: 'Look up multiple users by ID. Returns one line per requested ID in request order. Missing users are marked without failing the batch.',
      inputSchema: {
        type: 'object',
        properties: {
          user_ids: {
            type: 'array',
            items: { type: 'string' },
            minItems: 1,
            maxItems: 5,
            uniqueItems: true,
          },
        },
        required: ['user_ids'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'users_get_many') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Validate user_ids: must be an array
  if (!Array.isArray(args.user_ids)) {
    throw new Error('user_ids must be an array');
  }

  // Check for extra fields
  const allowedKeys = ['user_ids'];
  for (const key of Object.keys(args)) {
    if (!allowedKeys.includes(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  const ids = args.user_ids;

  // Non-empty
  if (ids.length < 1) {
    throw new Error('user_ids must be non-empty');
  }

  // At most 5
  if (ids.length > 5) {
    throw new Error('user_ids must have at most 5 entries');
  }

  // All must be strings
  for (const id of ids) {
    if (typeof id !== 'string') {
      throw new Error('user_ids must contain only strings');
    }
  }

  // Duplicate check
  const seen = new Set();
  for (const id of ids) {
    if (seen.has(id)) {
      throw new Error('user_ids must not contain duplicates');
    }
    seen.add(id);
  }

  // Build result - one line per id in request order
  const lines = [];
  for (const id of ids) {
    if (Object.prototype.hasOwnProperty.call(users, id)) {
      lines.push(`${id}: ${users[id].name}`);
    } else {
      lines.push(`${id}: (missing)`);
    }
  }

  const text = lines.join('\n');

  return {
    content: [
      {
        type: 'text',
        text,
      },
    ],
  };
}
"}

